    gloss: [['das Wochenende', 'weekend'], ['ausschlafen', 'to sleep in'], ['der Flohmarkt', 'flea market'], ['spazieren gehen', 'to go for a walk'], ['die Hausarbeit', 'housework'], ['die Wäsche waschen', 'to do the laundry'], ['sich ausruhen', 'to relax, rest'], ['letztes Wochenende', 'last weekend']],
